// Package builder generates the doors of an application (REST routes on
// echo, gRPC services, MCP tools, event functions and jobs) from @REST,
// @GRPC, @MCP, @Function and @Job annotations, on top of the fx modules
// generated by inject.
package builder

import (
	"go/types"
	"sort"

	"github.com/xgodev/boost/annotation"
	"github.com/xgodev/boost/inject"
)

// Kind is the protocol a server speaks.
type Kind string

const (
	// KindREST is an echo server serving @REST routes.
	KindREST Kind = "rest"
	// KindGRPC is a gRPC server serving @GRPC services.
	KindGRPC Kind = "grpc"
	// KindMCP is an MCP server serving @MCP tools.
	KindMCP Kind = "mcp"
)

// Spec is every door declared by the annotations, grouped by application.
type Spec struct {
	Apps []App // sorted by name
}

// App is one binary: its servers and, optionally, its event function, or
// its job alone.
type App struct {
	Name     string
	Servers  []Server  // sorted by name
	Function *Function // nil when the app has no @Function
	Job      *Job      // nil when the app has no @Job; an app with one has nothing else
	// Middlewares are the @Middleware of the constructors the doors of the
	// app build, sorted by constructor.
	Middlewares []Middleware
}

// Server is one echo, gRPC or MCP server of an app, with its own config path.
type Server struct {
	App      string
	Name     string
	Kind     Kind
	Routes   []Route   // KindREST, sorted by path then method
	Services []Service // KindGRPC, sorted by register function
	Tools    []Tool    // KindMCP, sorted by name
	// Plugins are the inject constructors of the []Plugin the server is built
	// with: the value named after the server, or the default (unnamed) value
	// for rest, grpc and mcp. Sorted by key.
	Plugins []inject.Component
	// PluginsName is the name Plugins are provided under, empty for the
	// default value and when there are no Plugins.
	PluginsName string
}

// Route is a @REST annotation: an HTTP method and path served by a handler.
type Route struct {
	Method  string // upper case
	Path    string
	Handler Handler
}

// Service is a @GRPC annotation: the value provided by an inject
// constructor, registered with a generated Register<Service>Server function.
type Service struct {
	Register string           // register function as written in the constructor's file
	Provider inject.Component // the annotated constructor
	Index    int              // result index of the service value
}

// Tool is a @MCP annotation: an MCP tool served by a handler.
type Tool struct {
	Name        string
	Description string // the doc comment of the handler
	Handler     Handler
}

// Function is a @Function annotation: the event handler of a function app,
// the adapter that feeds it and the middlewares it runs around the handler.
type Function struct {
	// Adapter is the adapter of adapter=x, or the first of adapter=[x, y]:
	// the one wired when <app>.function.adapter is unset.
	Adapter string
	// Alternatives are the other adapters of adapter=[x, y], in order, that
	// <app>.function.adapter may choose instead. Empty for a single adapter.
	Alternatives []string
	Handler      Handler
	Middlewares  []string // middleware names, the outermost first
	// Providers are the inject constructors of the values the middlewares
	// are built with, like the publisher.Driver of publisher. Sorted by key.
	Providers []inject.Component
	// ClientProviders are the inject constructors of the default clients the
	// adapters read with, by client type ("<import path>.<Type>"). inject
	// builds the default client of a type no constructor provides.
	ClientProviders map[string]inject.Component
	// Client is the name of the client the adapters read with, from
	// client=x; "" for the default client.
	Client string
}

// Job is a @Job annotation: the function a job app runs once before it exits.
type Job struct {
	Handler Handler
}

// Adapters returns the adapter and its alternatives, in order.
func (f Function) Adapters() []string {
	return append([]string{f.Adapter}, f.Alternatives...)
}

// DefaultClients returns the client types ("<import path>.<Type>") the
// adapters of the functions without client=x read with that no inject
// constructor provides, sorted: inject generates their default client for
// the function doors.
func (s Spec) DefaultClients() []string {
	var ids []string
	for _, ref := range s.adapterClients() {
		if ref.Name == "" {
			ids = append(ids, ref.ID)
		}
	}
	return ids
}

// NamedClients returns the clients the adapters of the functions with
// client=x read with that no inject constructor provides, sorted by type
// and name: inject generates them for the function doors.
func (s Spec) NamedClients() []inject.ClientRef {
	var refs []inject.ClientRef
	for _, ref := range s.adapterClients() {
		if ref.Name != "" {
			refs = append(refs, ref)
		}
	}
	return refs
}

// adapterClients returns the clients the adapters of the functions read
// with that no inject constructor provides, sorted by type and name.
func (s Spec) adapterClients() []inject.ClientRef {
	seen := map[inject.ClientRef]bool{}
	var refs []inject.ClientRef
	for _, app := range s.Apps {
		if app.Function == nil {
			continue
		}
		for _, name := range app.Function.Adapters() {
			for _, adapter := range functionAdapters[name] {
				ref := inject.ClientRef{ID: adapter.Client, Name: app.Function.Client}
				_, provided := app.Function.ClientProviders[adapter.Client]
				if adapter.Client == "" || provided || seen[ref] {
					continue
				}
				seen[ref] = true
				refs = append(refs, ref)
			}
		}
	}
	sort.Slice(refs, func(i, j int) bool {
		if refs[i].ID != refs[j].ID {
			return refs[i].ID < refs[j].ID
		}
		return refs[i].Name < refs[j].Name
	})
	return refs
}

// Handler is the annotated function or method serving a door.
type Handler struct {
	Entry annotation.Entry
	// Receiver is how a method gets its receiver; nil for a package function.
	Receiver *Receiver
}

// Receiver is the inject component providing the receiver of a handler method.
type Receiver struct {
	Type     string // provided type as written in the handler's package: "*Handler" or "Handler"
	Provider inject.Component
}

// Middleware is a @Middleware annotation: the plugins run around every method
// of the interface its constructor provides.
type Middleware struct {
	Provider  inject.Component // the annotated constructor
	Index     int              // result index of the interface value
	Plugins   []string         // plugin names, the outermost first
	Interface *types.Named     // the provided interface
	// Implementation is the implementation set the constructor is a member
	// of (@Default): the decorator runs only when config chooses it. Nil
	// for a constructor that is the only provider of its value.
	Implementation *inject.Implementation
}
